# =====================================================
# Calculate And Validate KPIs
# Scenario: Validate API data and calculate business KPIs
# =====================================================

# Get merged output from the previous node
input_data = _items[0]["json"]

orders = input_data.get("orders")
payments = input_data.get("payments")

errors = []

# -----------------------------------------------------
# 1. Validate input arrays
# -----------------------------------------------------

if not isinstance(orders, list):
    errors.append("Orders data is missing or is not a list.")

if not isinstance(payments, list):
    errors.append("Payments data is missing or is not a list.")

# Stop if either input array is missing or invalid
if errors:
    return [{
        "json": {
            "validation": {
                "isValid": False,
                "errors": errors
            }
        }
    }]

# -----------------------------------------------------
# 2. Validate order records
# -----------------------------------------------------

for order in orders:
    order_id = order.get("orderId", "unknown")
    amount = order.get("amount")
    status = order.get("status")

    if not order.get("orderId"):
        errors.append("Order record has a missing orderId.")

    # Reject strings, booleans, missing values and other
    # non-numeric amounts
    if not isinstance(amount, (int, float)) or isinstance(amount, bool):
        errors.append(
            f"Order {order_id}: amount must be a number."
        )
    elif amount < 0:
        errors.append(
            f"Order {order_id}: amount cannot be negative."
        )

    if status not in ["completed", "cancelled", "pending"]:
        errors.append(
            f"Order {order_id}: invalid status."
        )

# -----------------------------------------------------
# 3. Validate payment records
# -----------------------------------------------------

for payment in payments:
    payment_id = payment.get("paymentId", "unknown")
    payment_amount = payment.get("amount")
    payment_status = payment.get("status")

    if not payment.get("paymentId"):
        errors.append("Payment record has a missing paymentId.")

    if not payment.get("orderId"):
        errors.append(
            f"Payment {payment_id}: missing orderId."
        )

    if payment_status not in ["success", "failed", "pending"]:
        errors.append(
            f"Payment {payment_id}: invalid status."
        )

    if (
        not isinstance(payment_amount, (int, float))
        or isinstance(payment_amount, bool)
    ):
        errors.append(
            f"Payment {payment_id}: amount must be a number."
        )
    elif payment_amount < 0:
        errors.append(
            f"Payment {payment_id}: amount cannot be negative."
        )

# -----------------------------------------------------
# 4. Return validation errors if any exist
# -----------------------------------------------------

if errors:
    return [{
        "json": {
            "validation": {
                "isValid": False,
                "errors": errors
            }
        }
    }]

# -----------------------------------------------------
# 5. Calculate order KPIs
# -----------------------------------------------------

completed_orders = [
    order for order in orders
    if order["status"] == "completed"
]

cancelled_orders = [
    order for order in orders
    if order["status"] == "cancelled"
]

total_orders = len(orders)
completed_count = len(completed_orders)

total_revenue = sum(
    order["amount"] for order in completed_orders
)

order_success_rate = (
    completed_count / total_orders * 100
    if total_orders else 0
)

average_order_value = (
    total_revenue / completed_count
    if completed_count else 0
)

# -----------------------------------------------------
# 6. Calculate payment KPIs
# -----------------------------------------------------

successful_payments = [
    payment for payment in payments
    if payment["status"] == "success"
]

failed_payments = [
    payment for payment in payments
    if payment["status"] == "failed"
]

pending_payments = [
    payment for payment in payments
    if payment["status"] == "pending"
]

payment_attempts = len(payments)

payment_failure_rate = (
    len(failed_payments) / payment_attempts * 100
    if payment_attempts else 0
)

# -----------------------------------------------------
# 7. Prepare KPI report
# -----------------------------------------------------

report = {
    "reportDate": input_data.get("reportDate"),
    "currency": "INR",
    "totalOrders": total_orders,
    "completedOrders": completed_count,
    "cancelledOrders": len(cancelled_orders),
    "totalRevenue": round(total_revenue, 2),
    "orderSuccessRate": round(order_success_rate, 2),
    "averageOrderValue": round(average_order_value, 2),
    "paymentAttempts": payment_attempts,
    "successfulPayments": len(successful_payments),
    "failedPayments": len(failed_payments),
    "pendingPayments": len(pending_payments),
    "paymentFailureRate": round(payment_failure_rate, 2)
}

# -----------------------------------------------------
# 8. Return successful validation and calculated KPIs
# -----------------------------------------------------

return [{
    "json": {
        "validation": {
            "isValid": True,
            "errors": []
        },
        "kpis": report
    }
}]
